import { useState, useRef, useEffect, useCallback } from "react";
import { store } from "../../store";

// ── Shared metronome timing ────────────────────────────────────────────────
// Single source of truth for bpm/beats/running/beat — both the audible
// widget (ScoreMetronome) and the silent visual border pulse
// (VisualMetronomeBorder) consume ONE instance of this hook so they can
// never drift relative to each other, even across tempo changes. `muted`
// lets either surface run with or without sound — the beat/visual pulse
// keeps going either way, only the click is skipped.
export function useMetronomeEngine() {
  const [bpm, setBpm]       = useState(80);
  const [beats, setBeats]   = useState(4);
  const [running, setRun]   = useState(false);
  const [beat, setBeat]     = useState(0);
  const [muted, setMutedRaw] = useState(() => store.get("metronome-muted", false));
  const audioRef    = useRef(null);
  const intervalRef  = useRef(null);
  const beatRef      = useRef(0);

  const setMuted = useCallback((v) => {
    setMutedRaw(v);
    store.set("metronome-muted", v);
  }, []);
  const toggleMuted = useCallback(() => setMuted(!muted), [muted, setMuted]);

  const click = useCallback((accent) => {
    if (muted) return;
    if (!audioRef.current)
      audioRef.current = new (window.AudioContext || window.webkitAudioContext)();
    const ctx = audioRef.current;
    const osc = ctx.createOscillator();
    const g   = ctx.createGain();
    osc.connect(g); g.connect(ctx.destination);
    osc.frequency.value = accent ? 1200 : 900;
    g.gain.setValueAtTime(accent ? 0.4 : 0.25, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
    osc.start(); osc.stop(ctx.currentTime + 0.09);
  }, [muted]);

  useEffect(() => {
    if (running) {
      beatRef.current = 0;
      click(true); setBeat(1);
      intervalRef.current = setInterval(() => {
        beatRef.current = (beatRef.current + 1) % beats;
        click(beatRef.current === 0);
        setBeat(beatRef.current + 1);
      }, (60 / bpm) * 1000);
    } else {
      clearInterval(intervalRef.current);
      setBeat(0);
    }
    return () => clearInterval(intervalRef.current);
  }, [running, bpm, beats, click]);

  useEffect(() => () => clearInterval(intervalRef.current), []);

  // Toggling play must create/resume the AudioContext SYNCHRONOUSLY inside
  // the click handler itself — Safari/iOS refuses to unlock audio for a
  // context first touched later inside a useEffect (a separate task from
  // the user gesture), which is exactly what happens if `click()` is left
  // to lazily create it on the first interval tick instead.
  const toggleRunning = useCallback(() => {
    if (!audioRef.current) {
      audioRef.current = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (audioRef.current.state === "suspended") {
      audioRef.current.resume().catch(() => {});
    }
    setRun(r => !r);
  }, []);

  return { bpm, setBpm, beats, setBeats, running, setRunning: setRun, toggleRunning, beat, muted, setMuted, toggleMuted };
}
